void FSingleShapePairCollisionDetector::WakeCollision(const int32 SleepEpoch, const int32 CurrentEpoch)
{
	if (Constraint.IsValid() && IsUsedSince(SleepEpoch))
	{
		if (bChaosMidPhaseActivateWakingConstraints)
		{
			ReactivateCollisionConstraint(Constraint.Get());
			LastUsedEpoch = Constraint->GetContainerCookie().LastUsedEpoch;
		}
		else
		{
			// We need to refresh the epoch so that the constraint state will be used as the previous
			// state if the pair is still colliding in the next tick. However, we are not in the active 
			// collisions array so reset the indices.
			Constraint->GetContainerCookie().LastUsedEpoch = CurrentEpoch;
			Constraint->GetContainerCookie().ConstraintIndex = INDEX_NONE;
			Constraint->GetContainerCookie().CCDConstraintIndex = INDEX_NONE;
			LastUsedEpoch = CurrentEpoch;
		}

		// We have skipped collision detection for this particle because it was asleep, so we need to update the transforms...
		// NOTE: this relies on the shape world transforms being up-to-date. They are usually updated in Integrate which
		// is also skipped for sleeping particles, so they must be updated manually when waking partciles (see IslandManager)
		Constraint->SetShapeWorldTransforms(Shape0->GetLeafWorldTransform(GetParticle0()), Shape1->GetLeafWorldTransform(GetParticle1()));

// CollisionTolerance:
// For polygonal shapes the collision tolerance is proportional to the size of the smaller object. 
// For quadratic shapes we want a collision tolerance much smaller than the radius.
//
const bool bIsQuadratic0 = ((ImplicitType0 == ImplicitObjectType::Sphere) || (ImplicitType0 == ImplicitObjectType::Capsule));
const bool bIsQuadratic1 = ((ImplicitType1 == ImplicitObjectType::Sphere) || (ImplicitType1 == ImplicitObjectType::Capsule));

// @todo(chaos): should probably be tunable. Used to use the same settings as the margin scale (for convex), but we want to support zero
// margins, but still have a non-zero CollisionTolerance (it is used for matching contact points for friction and manifold reuse)
const FRealSingle ToleranceScale = 0.1f;
const FRealSingle QuadraticToleranceScale = 0.05f;

if (!bIsQuadratic0 && !bIsQuadratic1)
{
	// Only dynamic polytopes objects use margins
	const bool bIsDynamic0 = (GetParticle0() != nullptr) && (FConstGenericParticleHandle(GetParticle0())->IsDynamic());
	const bool bIsDynamic1 = (GetParticle1() != nullptr) && (FConstGenericParticleHandle(GetParticle1())->IsDynamic());
	const FRealSingle DynamicMargin0 = bIsDynamic0 ? FRealSingle(Margin0) : FRealSingle(0);
	const FRealSingle DynamicMargin1 = bIsDynamic1 ? FRealSingle(Margin1) : FRealSingle(0);

	const FRealSingle MaxSize0 = ((Implicit[0] != nullptr) && Implicit[0]->HasBoundingBox()) ? FRealSingle(Implicit[0]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
	const FRealSingle MaxSize1 = ((Implicit[1] != nullptr) && Implicit[1]->HasBoundingBox()) ? FRealSingle(Implicit[1]->BoundingBox().Extents().GetAbsMax()) : FRealSingle(0);
	const FRealSingle MaxSize = FMath::Min(MaxSize0, MaxSize1);
	CollisionTolerance = ToleranceScale * MaxSize;

	// If one shape has a zero margin, enforce a minimum margin to avoid the EPA degenerate case. E.g., Box-Triangle

manifolds.extend(new_manifolds.iter().filter_map(|manifold| {
    // Skip empty manifolds.
    if manifold.contacts().is_empty() {
        return None;
    }

    let subpos1 = manifold.subshape_pos1.unwrap_or_default();
    let local_normal: Vector = (subpos1.rotation * manifold.local_n1).normalize();
    let normal = rotation1 * local_normal;

    // Make sure the normal is valid
    if !normal.is_normalized() {
        return None;
    }

    let points = manifold.contacts().iter().map(|contact| {
        // The contact point is the midpoint of the two points in world space.
        // The anchors are relative to the positions of the colliders.
        let point1 = rotation1 * subpos1.transform_point(contact.local_p1);
        let anchor1 = point1 + normal * contact.dist * 0.5;
        let anchor2 = anchor1 + (position1.0 - position2.0);
        let world_point = position1.0 + anchor1;
        ContactPoint::new(anchor1, anchor2, world_point, -contact.dist)
            .with_feature_ids(contact.fid1.into(), contact.fid2.into())
    });

    let manifold = ContactManifold::new(points, normal);

    Some(manifold)

// Save the old manifolds for warm starting.
let old_manifolds = contacts.manifolds.clone();

// TODO: It'd be good to persist the manifolds and let Parry match contacts.
//       This isn't currently done because it requires using Parry's contact manifold type.
// Compute the contact manifolds using the effective speculative margin.
let context = ContactManifoldContext::new(
    collider1.entity,
    collider2.entity,
    collider_context,
